<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require __DIR__.'/includes/project_manager.php';require_permission('project_time.manage');$pdo=db();$projectId=(int)($_GET['project_id']??$_POST['project_id']??0);$taskId=(int)($_GET['task_id']??$_POST['task_id']??0);$projects=pm_project_options($pdo);if(!$projectId&&$projects)$projectId=(int)$projects[0]['id'];$tasks=[];if($projectId){$q=$pdo->prepare("SELECT id,title FROM project_tasks WHERE project_id=? ORDER BY status='done',title");$q->execute([$projectId]);$tasks=$q->fetchAll();}$pageTitle='Registrar horas';$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$projectId=(int)($_POST['project_id']??0);$hours=(float)($_POST['hours']??0);if(!$projectId)$errors[]='Selecciona un proyecto.';if($hours<=0)$errors[]='Las horas deben ser mayores a cero.';if(!$errors){$pdo->prepare('INSERT INTO project_time_entries(project_id,task_id,user_id,work_date,hours,billable,hourly_rate,description) VALUES (?,?,?,?,?,?,?,?)')->execute([$projectId,(int)($_POST['task_id']??0)?:null,(int)$_SESSION['user_id'],($_POST['work_date']??date('Y-m-d'))?:date('Y-m-d'),$hours,isset($_POST['billable'])?1:0,max(0,(float)($_POST['hourly_rate']??0)),trim((string)($_POST['description']??''))?:null]);flash('success','Horas registradas.');redirect('project_timesheet.php?project_id='.$projectId);}}require __DIR__.'/includes/header.php';?><?php foreach($errors as$e):?><div class="alert alert-error"><?=e($e)?></div><?php endforeach;?><form method="post" class="panel"><div class="panel-header"><div><h2>Registrar horas</h2><span class="table-sub">Carga tiempo trabajado en un proyecto o tarea.</span></div><a class="btn btn-light btn-small" href="project_timesheet.php?project_id=<?=$projectId?>">Volver</a></div><div class="panel-body form-grid"><?=csrf_field()?><label>Proyecto<select name="project_id" required onchange="location='project_time_form.php?project_id='+this.value"><?php foreach($projects as$p):?><option value="<?=$p['id']?>" <?=$projectId===(int)$p['id']?'selected':''?>><?=e($p['name'])?></option><?php endforeach;?></select></label><label>Tarea<select name="task_id"><option value="0">Sin tarea específica</option><?php foreach($tasks as$t):?><option value="<?=$t['id']?>" <?=$taskId===(int)$t['id']?'selected':''?>><?=e($t['title'])?></option><?php endforeach;?></select></label><label>Fecha<input type="date" name="work_date" value="<?=e($_POST['work_date']??date('Y-m-d'))?>"></label><label>Horas<input type="number" step="0.25" min="0.25" name="hours" required value="<?=e($_POST['hours']??1)?>"></label><label>Tarifa por hora<input type="number" step="0.01" min="0" name="hourly_rate" value="<?=e($_POST['hourly_rate']??0)?>"></label><label class="check-row"><input type="checkbox" name="billable" value="1" checked> Facturable</label><label class="full">Descripción<input name="description" value="<?=e($_POST['description']??'')?>" placeholder="Qué trabajo se realizó"></label><div class="full form-actions"><button class="btn btn-primary">GUARDAR HORAS</button></div></div></form><?php require __DIR__.'/includes/footer.php';?>
